import { encode } from "next-auth/jwt";
import { mkdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";

const SESSION_COOKIE_NAME = "authjs.session-token";

/**
 * Create a real Auth.js-encrypted test session for the local Playwright server.
 * The short-lived secret is generated by playwright.config.ts for this run;
 * no application auth bypass or Google credentials are used.
 */
export default async function globalSetup(): Promise<void> {
  const secret = process.env.STUDYRUNWAY_E2E_AUTH_SECRET;
  if (!secret) {
    throw new Error(
      "Playwright test auth secret is missing. Run the E2E suite through playwright.config.ts.",
    );
  }

  const now = Math.floor(Date.now() / 1000);
  const maxAge = 60 * 60;
  const value = await encode({
    token: {
      sub: "studyrunway-e2e-user",
      name: "StudyRunway E2E",
      email: "studyrunway-e2e@example.invalid",
      picture: null,
    },
    secret,
    salt: SESSION_COOKIE_NAME,
    maxAge,
  });

  const storageStatePath = resolve(process.cwd(), "test-results/e2e-auth-state.json");
  await mkdir(dirname(storageStatePath), { recursive: true });
  await writeFile(
    storageStatePath,
    `${JSON.stringify(
      {
        cookies: [
          {
            name: SESSION_COOKIE_NAME,
            value,
            domain: "localhost",
            path: "/",
            expires: now + maxAge,
            httpOnly: true,
            secure: false,
            sameSite: "Lax",
          },
        ],
        origins: [],
      },
      null,
      2,
    )}\n`,
    { encoding: "utf8", mode: 0o600 },
  );
}
